"""Explicit source-order review of SCSA 2027 Unit 3; labels are paraphrases."""
from reconciliation_common import publish,R
from html import escape as H
P=R/'practical-packs/unit3-evidence';P.mkdir(parents=True,exist_ok=True)
source='https://senior-secondary.scsa.wa.edu.au/__data/assets/pdf_file/0006/1273182/Applied-Information-Technology-ATAR-Year-12-Syllabus-for-teaching-from-2027.PDF'
bridges={}
def bridge(key,title,chapter,section,models,steps,checks,question,answer,extra=''):
 extra+='<h3>Check your reasoning</h3><p>'+H(question)+'</p><details><summary>Compare your explanation</summary><p>'+H(answer)+'</p></details><h3>Production sequence</h3><ol>'+''.join('<li>'+H(s)+'</li>' for s in steps)+'</ol>'
 bridges[key]=dict(title=title,chapter=chapter,section=section,models=models,task='Complete the production sequence using your own version of the festival brief. Change the venue and one user access need, then justify and test the resulting revision. Retain your own outputs and observations; the supplied reference is a model.',checks=checks,extra=extra)

bridge('interface','Annotate, test and revise a festival interface','u3-design','explain-the-design-relationship',[
 ['Task and hierarchy','A visitor must find the 10:00 printmaking session and its room. Programme → Session details gives a labelled path; the reference has a visible return route. A hierarchy describes relationships rather than only a list of pages.'],
 ['Element → principle → effect','The larger, darker session heading uses size and tone to create emphasis. Space groups time and venue by proximity; a repeated heading treatment supports unity. The intended result is easier scanning, which still needs a task observation.'],
 ['GUI and help','The reference uses labelled links and expandable help beside the programme. A touchscreen kiosk may need different target spacing from a desktop. Help describes what a visitor can do; an icon alone may be ambiguous.'],
 ['Usability, inclusion, accessibility','Task success and effort address usability. Keyboard operation and meaningful text are accessibility checks. An offline printed route and plain language can reduce participation barriers. These questions overlap but are not interchangeable.'],
 ['Critical analysis','A decorative label may appear balanced while obscuring a caption. Preserve the required information, revise its placement, then compare the same task in the revised version. A claimed principle does not prove an effective outcome.']],
 ['Copy the supplied festival.html and festival.css into your own folder. Open the unchanged reference and complete the session-finding task.',
  'Draw a revised layout and annotate at least three choices with element, principle, intended task effect and a possible drawback. Create a site map with return routes.',
  'Implement your changed venue/access need using labelled navigation and relevant help. Keep content order logical without relying on colour alone.',
  'Test keyboard-only navigation, visible focus, 200% text enlargement and a narrow/wide viewport. Record the actual environment and task result.',
  'Identify one problem, revise the source and repeat the same check. Explain whether the evidence supports your intended design effect.'],
 ['Annotated before/after design and hierarchy map.','Source copies, expected/actual observations, revision and retest.','State which users and access methods were not tested.'],
 'A visitor likes the colours but cannot find the room. Has the task passed?',
 'No. Preference is one response; the room-finding task failed. Investigate grouping, labels and help, revise the cause and repeat that task.',
 '<p><a href="festival.html">Open the working festival guide</a> · <a href="festival.html" download>Download editable HTML</a> · <a href="festival.css" download>Download shared CSS</a></p>')

bridge('devices','Gate device suitability before ranking extra features','u3-hardware','use-a-requirement-gate-before-ranking-extras',[
 ['Fictional brief','A walking volunteer needs offline HTML access for four hours, readable venue details and a portable device. A producer separately needs the approved multi-track editor. These are different roles.'],
 ['Option A: supplied model evidence','Fictional tablet: 8 GB RAM, 64 GB free, offline HTML supported; supplied scenario trial lasts 4.5 hours at the stated brightness. Field use passes only the model criteria; the desktop editor is unsupported. These are invented exercise data, not measurements made by the textbook.'],
 ['Option B: supplied model evidence','Fictional desktop: 16 GB RAM, 300 GB free, editor supported, mains power required. Suitable for a fixed production role, but fails the walking/mobility requirement. Extra RAM cannot repair that failure.'],
 ['Option C: supplied model evidence','Fictional phone: 8 GB RAM, 32 GB free, offline support claimed; task readability and runtime unknown. Mark these unverified. Do not convert a supplier claim into a passed trial.'],
 ['Specification and usability','RAM is working memory; free storage is available file capacity. OS/app support, screen readability, input, connections and workload runtime affect different tasks. Compare the same workload and conditions.'],
 ['Trend and convergence','Use the linked historical primary-source comparison to study changing device form factors. It is dated evidence, not a claim about the newest product. Combining camera, schedule and messaging reduces equipment but concentrates battery and access dependence.']],
 ['Define two essential field criteria and two production criteria, including user/context and how each will be checked.',
  'Create an A/B/C table with pass, fail and unverified against the supplied fictional data. Explain at least two specification-to-task relationships.',
  'Use the dated trend case, then find a current primary source in an approved research session. Record publication/access dates, exact claim and limits; identify what is actually changing over time.',
  'Recommend roles or a combined workflow, state missing evidence, propose a representative trial and a fallback. No purchase or new account is required.'],
 ['Separate fictional model data, manufacturer statements and your actual observations.','Record dates and conditions for any real device comparison.','Retain failed essentials and unknowns rather than a single unexplained score.'],
 'C has the same RAM as A. Can C inherit A’s runtime result?',
 'No. Runtime depends on the device, workload and conditions. C remains unverified for that criterion.',
 '<p><a href="../worked-cases/mobile-trend.html">Dated device-trend evidence and source limits</a></p>')

bridge('rights','Separate ownership, access and publication decisions','u3-impacts','identify-which-right-is-in-question',[
 ['IP and purpose','Intellectual property includes distinct rights. Copyright concerns specified uses of protected expression, while a design right concerns qualifying product appearance. Their purposes include giving creators/owners control under their respective schemes; credit alone is not universal reuse permission.'],
 ['Asset decision','A fictional contributor supplies a photograph for a classroom draft only. A public festival page is a different use. Keep the stated terms and seek the needed permission through the teacher; do not treat folder access as permission.'],
 ['Defamation case','A draft makes an unsupported accusation about an identifiable fictional organiser. Reputation harm, publication context, legal requirements and possible defences matter; being offensive alone does not decide liability. Pause the allegation and preserve an appropriate review record.'],
 ['Response routes','Removal/correction requests, specialist advice and potentially civil proceedings are different routes. Court action may seek compensation; entitlement, procedure and outcome depend on the case. The exercise does not contact anyone or predict a legal result.'],
 ['FOI scope','For a fictional Australian Government report, the Commonwealth FOI framework concerns access to held documents, with exemptions and review routes. It is not a right to every private shop file. Make the scope clear and follow the applicable procedure.'],
 ['Access versus reuse','A report released under FOI can still contain material needing a separate reuse decision. Check the proposed excerpt/image, applicable terms and publication concerns rather than assuming release clears everything.']],
 ['Create a register for three invented festival assets/claims: creator/source, proposed use, terms, missing permission and reviewer.',
  'Classify a photograph reuse question, a product-appearance question and an unsupported fictional allegation. Explain the distinct rights/issues and evidence needed.',
  'Draft a hypothetical, narrowly scoped Commonwealth FOI document description and one possible limit/review route. Do not submit a request.',
  'Record an editorial decision for each asset/claim and explain why access, authorship credit and publication permission are separate.'],
 ['Use fictional names and allegations only.','Link current primary guidance with access dates; refer unresolved real cases for qualified review.','Do not describe the exercise as a legal determination.'],
 'A government report has been released. Does that automatically authorise a festival poster using every photograph?',
 'No. Access and the proposed reproduction are separate decisions; inspect the relevant rights and conditions.',
 '<p>Guidance checked 27 October 2026: <a href="https://www.ipaustralia.gov.au/design-rights">IP Australia</a> · <a href="https://www.ag.gov.au/rights-and-protections/copyright/copyright-owners">Attorney-General’s Department</a> · <a href="https://www.legalaid.wa.gov.au/node/365">Legal Aid WA</a> · <a href="https://www.oaic.gov.au/freedom-of-information/your-freedom-of-information-rights/what-is-freedom-of-information">OAIC FOI</a>.</p>')

bridge('collaboration','Choose tools and preserve a shared decision record','u3-impacts','choose-collaboration-for-the-task',[
 ['Physical','A shared-room prototype review supports immediate discussion and shared equipment; travel, room availability and access can exclude participants. Keep a written decision record.'],
 ['Virtual','An approved shared document supports remote comments and version history; connection, permissions and software access remain dependencies. A call supports discussion but needs an accessible record of agreed actions.'],
 ['Hybrid and online tools','Use an available shared document/task board for owners, versions and approval, with a short meeting for unresolved decisions. An approved browser editor may support production, but confirm supported formats, export and offline availability. No particular vendor or new account is required.'],
 ['Convergence effect','One mobile tool can capture, edit and send a draft quickly. That concentrates failure and can distribute unapproved content faster. Keep approval and a copy of agreed output before handover.']],
 ['Compare physical, virtual and hybrid methods for two volunteers: one remote, one with unreliable connectivity. Include advantages, disadvantages and implications for access and review.',
  'Choose an approved existing shared tool if available; otherwise rehearse roles locally and label the online-operation skill unverified. Record owner, reviewer, version, change and decision.',
  'Have a peer propose a change, review it and retain the agreed version. Test opening/exporting it in the chosen production application.',
  'Analyse one converged workflow and a failure fallback; show how an approved offline change is reconciled with the shared record.'],
 ['Keep a permissions/format/access check and actual version or review history.','Separate a local role rehearsal from actual operation of an online application.','Explain a dependency and who resolves conflicting edits.'],
 'Does a video call by itself establish which draft was approved?',
 'No. Record the agreed version, decision, owner and remaining actions in a shared accessible record.')

bridge('timeline','Produce a multi-track edit and inspect the delivered mix','u3-applications','arrange-video-across-tracks',[
 ['Layer plan','Use the existing twelve-second source sequence as a starting point. Base picture occupies video track 1; title/venue overlays use track 2. Their timing and stacking determine the combined image.'],
 ['Titles/transitions/effects','Show the title long enough to read, use a motivated cut or transition between locations and apply only an effect that serves the brief. An effect name alone does not justify its use. Check whether captions or venue text are obscured.'],
 ['Sound','Keep narration and supporting sound on separate tracks. A sound effect can cue a scene change; check it does not mask speech. Source peaks and final intelligibility are separate checks.'],
 ['Editable versus delivery','The linked production pack supplies a source specification, actual media exports and measured checks. A finished movie is not an editor-native multi-track project. Save your own application project and a reopened delivery copy.'],
 ['Interactivity','The festival guide has links and a native expandable-help control. A video file alone does not establish interactivity; implement a meaningful action and test its result and keyboard operation.']],
 ['Open the linked editable media starter in approved software; retain the original and save an application-native working project.',
  'Create your own short sequence with at least two picture layers or multiple audio tracks, title, transition and purposeful effect; use approved/original assets.',
  'Edit a supporting sound effect and speech balance. Record intended timing and actual output observations rather than assuming the preview proves the export.',
  'Export, reopen and inspect the full delivery copy for timing, intelligibility, readable labels and caption overlap. Record settings, player and actual duration.',
  'Link or integrate the output in your own interactive festival product; test one meaningful action, revise a problem and retest.'],
 ['Retain native project, source assets/terms, delivered media and settings.','Keep separate expected and observed results with revision/retest.','Reading or playing the supplied model does not demonstrate production skill.'],
 'The preview is correct but the exported title covers a caption. Which result decides delivery readiness?',
 'The delivery copy fails that criterion. Revise the timing/layout and export again, then repeat the check in the target player.',
 '<p><a href="../production-workflows/multitrack.html">Actual multi-track export reference</a> · <a href="../animation-multimedia/timeline.html">Editable timeline starter</a> · <a href="festival.html">Interactive product reference</a></p>')

bridge('publication','Build a reusable layout and separate screen and print output','u3-applications','build-a-reusable-publication-structure',[
 ['Publication choice','An HTML guide supports navigation and updates; a printed sheet works without a charged device but cannot play media and needs a replacement when details change. A PDF can preserve layout, yet interactive behaviour and accessibility need their own checks. Match the type to the task.'],
 ['Template and frames','The supplied HTML/CSS template repeats a header, session cards and help. Cards act as content containers; in publishing software, text/image frames control placement and overflow. A template is an editable structure, not only a screenshot.'],
 ['Layers and typography','Separate background decoration, text and image/overlay roles. Keep readable heading/body relationships, logical reading order and intentional spacing. A layer arrangement that looks correct may still hide text or export incorrectly.'],
 ['Scheme versus profile','A colour scheme selects related colours for communication. A colour profile describes colour interpretation for a device/output workflow. Selecting a blue palette does not assign, convert or verify an ICC profile.'],
 ['Output-specific checks','The template’s print stylesheet removes navigation/help controls and keeps the session information in text. This is an editable HTML reference, not an ICC-verified press-ready file. Use the linked tagged/untagged artwork and output brief for actual profile/export/proof operations.']],
 ['Choose a digital publication type for a stated visitor task and justify it against another type, including a limitation.',
  'Copy and modify the supplied template in approved software. Create a second session using the same layout pattern; keep venue/time content specific.',
  'Use layers, frames/containers and deliberate typography; check overflow, reading order and required information after editing.',
  'For a screen brief, inspect the delivered layout and interactions. For print, use the linked publication pack to record actual colour-profile handling and output settings required by that brief.',
  'Reopen both outputs and inspect or proof them in the intended context. Retain source, output settings, actual observations and one revised/retested issue.'],
 ['Retain an editable template and produced publication, not just the supplied reference.','Record actual profile name/operation when the application supports it; otherwise mark that operation unverified.','Browser print preview alone does not establish professional print/profile conformance.'],
 'The web colours look attractive. Has the print colour-profile skill been demonstrated?',
 'No. A palette and a profile are different. The actual application operation and required output/proof checks need their own record.',
 '<p><a href="festival.html" download>Editable HTML template</a> · <a href="festival.css" download>Editable screen/print stylesheet</a> · <a href="../publication-workflow/index.html">Colour-profile assets, output briefs and proofing workflow</a></p>')

bridge('planning','Connect the brief, design drawings and feasible schedule','u3-projects','put-durations-dependencies-and-resources-in-the-schedule',[
 ['Brief and approach','The fictional client wants a readable guide for two sessions, with an offline option. Record requirements, constraints, deliverables, criteria, roles and approvals. Prototype the uncertain navigation; use structured checkpoints for approved content and production. Neither approach guarantees success.'],
 ['Purposeful drawings','A storyboard sequences a media introduction. A site map relates programme and session destinations. A flow chart describes a visitor decision. A visual layout positions heading, controls and content. Label assumptions so a reviewer can challenge them.'],
 ['Worked schedule','Six illustrative day blocks: D1 confirm brief; D2 prototype review and asset preparation with two different available people; D3–4 build after both; D5 test; D6 revise/retest. These are estimates, not observed progress or extra teaching weeks.'],
 ['Resource counterexample','If one person must do both D2 tasks, they cannot both occupy that person for the same full day. Move one task or agree another resourcing/scope option, then update dependent build and handover dates.'],
 ['Tools and management','Use approved project software, a board or spreadsheet to record owner, duration, predecessors, status and decisions. Gantt bars show periods; predecessor logic and resource checks establish whether the proposed plan is feasible.'],
 ['Evaluate distinct questions','Structure: information relationships. UI: controls/presentation. Usability: task performance. Accessibility: disability-related barriers. UX: broader perceptions/responses. Retain evidence and limits for each rather than one “looks good” verdict.']],
 ['Develop your detailed brief with the teacher acting as client; define observable success criteria and the approval record.',
  'Compare prototype and structured approaches, choose a justified approach and produce annotated draft layouts with approved layout tools.',
  'Create a storyboard, site map and decision flow chart where they resolve different planning questions. Use the linked reference as a model, not your own finished work.',
  'Create a Gantt/task plan with estimates, dependencies, owners, milestones and a resource-capacity check. Record a changed access/venue requirement and revise the plan.',
  'Build your product under the plan, update actual progress, then test criteria, revise and retest. Hand over source/delivery files, rights records and known limitations.'],
 ['Keep brief versions, drawings, schedule, changes and actual progress.','Trace a design choice to a criterion and its observed check.','Do not mark a task complete merely because its planned date passed.'],
 'Prototype approval is complete, but a required image is not cleared. Can the whole build automatically start?',
 'No. Identify which work depends on that asset. Continue unblocked work only with an agreed plan; update dependencies and record the unresolved permission.',
 '<p><a href="planning-model.html">Storyboard, site map, decision flow and schedule model</a> · <a href="evidence-log.csv" download>Blank observation log</a></p>')

rows=[]
def add(area,kind,page,n,label,key,section,children=()):
 root=f'{kind[0]}{n}';base=f'U3-{area.upper()}-{root}';b=bridges[key]
 def item(id,path,label,parent='',context=False):
  rows.append(dict(id=id,area=area,kind=kind,page=page,locator=f'{area} / {kind} / {path}',summary=label,parent=parent,context=context,explanation=f'../../index.html#topic/{b["chapter"]}/{section}',worked=f'{key}.html#worked',practice=f'{key}.html#independent',evidence=f'{key}.html#checks',status='Parent context: review child rows' if context else 'Authored task/model located; performance unverified' if kind=='Skills' else 'Authored explanation/model/task located; review pending',limitation='Independent subject review pending.'+(' Actual learner output and observations remain unverified.' if kind=='Skills' else '')))
 item(base,root,label,context=bool(children))
 for i,child in enumerate(children,1):
  if isinstance(child,tuple):
   name,leaves=child;pid=f'{base}.{i}';item(pid,f'{root}.{i}',name,base,True)
   for j,leaf in enumerate(leaves,1):item(f'{pid}.{j}',f'{root}.{i}.{j}',leaf,pid)
  else:item(f'{base}.{i}',f'{root}.{i}',child,base)

