(P/'festival.html').write_text('''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Community festival · editable reference</title><link rel="stylesheet" href="festival.css"></head><body><a class="skip" href="#main">Skip to programme</a><header><p>FICTIONAL CLASSROOM REFERENCE</p><h1>Community festival</h1><p>Find a session, its time and its room.</p><nav aria-label="Festival sections"><a href="#programme">Programme</a><a href="#printmaking">Printmaking details</a><a href="#photography">Photography details</a></nav></header><main id="main" tabindex="-1"><section id="programme" aria-labelledby="programme-title"><h2 id="programme-title">Programme</h2><p>Saturday · invented event details for classroom editing.</p><div class="cards"><article><h3>Printmaking</h3><p><time datetime="10:00">10:00</time> · Studio 1</p><p>Make a simple two-colour print.</p><a href="#printmaking">Read printmaking details</a></article><article><h3>Photography</h3><p><time datetime="11:30">11:30</time> · Studio 2</p><p>Explore composition using an approved classroom device.</p><a href="#photography">Read photography details</a></article></div><details><summary>Help finding a session</summary><p>Choose a session’s labelled details link. The details show its time and room. Use “Back to programme” to compare another session. For access arrangements, ask the teacher acting as event coordinator; this reference sends no information.</p></details></section><section id="printmaking" aria-labelledby="print-title"><h2 id="print-title">Printmaking details</h2><p><strong>Time:</strong> 10:00–11:00. <strong>Room:</strong> Studio 1.</p><p>Classroom materials are provided. Check any access arrangements with the teacher before the activity.</p><a href="#programme">Back to programme</a></section><section id="photography" aria-labelledby="photo-title"><h2 id="photo-title">Photography details</h2><p><strong>Time:</strong> 11:30–12:30. <strong>Room:</strong> Studio 2.</p><p>Use original or approved images. The activity offers a seated composition alternative.</p><a href="#programme">Back to programme</a></section></main><footer><p>Editable HTML/CSS model. The text remains available in print; navigation controls are omitted.</p><p><a href="interface.html">Interface task</a> · <a href="publication.html">Publication task</a> · <a href="index.html">Unit 3 resources</a></p></footer></body></html>''',encoding='utf-8')
(P/'festival.css').write_text('''*{box-sizing:border-box}html{scroll-padding-top:1rem}body{margin:0;background:#f8f5ee;color:#213b35;font:1.1rem/1.6 system-ui,sans-serif}header,main,footer{max-width:60rem;margin:auto;padding:1.5rem}header{border-bottom:4px solid #426451}h1{font-size:clamp(2rem,5vw,3.5rem);line-height:1.15}h2,h3{line-height:1.3}a{color:#164e77;text-underline-offset:.2em;overflow-wrap:anywhere}nav{display:flex;flex-wrap:wrap;gap:1rem}a,summary{min-height:44px;display:inline-block;padding:.35rem .1rem}summary{display:list-item;cursor:pointer}section{margin-block:2rem;scroll-margin-top:1rem}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.cards article{border:1px solid #9ba99e;background:white;padding:1rem;min-width:0}details{padding:1rem;background:#e7eee7;margin-block:1rem}:focus-visible{outline:3px solid #754600;outline-offset:4px}.skip{position:absolute;left:-10000px}.skip:focus{position:static;margin:1rem}.cards article h3{margin-top:0}@media(max-width:600px){.cards{grid-template-columns:1fr}header,main,footer{padding:1rem}}@media print{body{background:white;color:black;font:11pt/1.4 sans-serif}nav,.skip,details,footer a,section>a,.cards a{display:none}header,main,footer{max-width:none;padding:0}section{break-inside:avoid}.cards{grid-template-columns:1fr 1fr}h1{font-size:24pt}.cards article{border:1px solid black}a{color:black}}
''',encoding='utf-8')

# Original editable vector planning drawings, paired with the page's text equivalents.
def svg(file,title,description,height,body):
 (P/file).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="900" height="{height}" viewBox="0 0 900 {height}" role="img" aria-labelledby="title desc"><title id="title">{H(title)}</title><desc id="desc">{H(description)}</desc><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#426451"/></marker></defs><rect width="900" height="{height}" fill="#f8f5ee"/><g font-family="sans-serif" font-size="19" fill="#213b35">{body}</g></svg>',encoding='utf-8')
svg('storyboard.svg','Twelve-second festival storyboard','Three four-second panels: festival title, venue approach and venue label. Captions and narration are planned separately.',260,'''<text x="30" y="35" font-size="24">Storyboard · planned sequence, not recorded playback</text><g stroke="#426451" fill="white"><rect x="30" y="60" width="260" height="150"/><rect x="320" y="60" width="260" height="150"/><rect x="610" y="60" width="260" height="150"/></g><text x="45" y="90">0–4 seconds</text><text x="45" y="130">Festival title</text><text x="45" y="165">Establishing scene</text><text x="335" y="90">4–8 seconds</text><text x="335" y="130">Approach to venue</text><text x="335" y="165">Explain programme</text><text x="625" y="90">8–12 seconds</text><text x="625" y="130">Venue label</text><text x="625" y="165">Keep captions clear</text><text x="30" y="242">Separate picture, labels and narration in the editable timeline.</text>''')
svg('site-map.svg','Festival information hierarchy','Programme is the parent with Printmaking and Photography child sections. Both details sections return to Programme. Help is available beside the programme.',300,'''<text x="30" y="35" font-size="24">Site map · same-page section destinations</text><g stroke="#426451" fill="white"><rect x="315" y="60" width="270" height="60"/><rect x="80" y="185" width="300" height="60"/><rect x="520" y="185" width="300" height="60"/></g><g fill="none" stroke="#426451" stroke-width="3" marker-end="url(#arrow)"><path d="M380 120L240 185"/><path d="M520 120L660 185"/><path d="M210 185L350 120"/><path d="M690 185L550 120"/></g><text x="395" y="98">Programme</text><text x="130" y="223">Printmaking details</text><text x="565" y="223">Photography details</text><text x="30" y="280">Each detail returns to Programme. Contextual help sits beside the programme.</text>''')
svg('decision-flow.svg','Route decision flow','Open programme, choose a session, read time and room, then decide whether the route is usable. Yes leads to follow route and finish. No leads to ask for access arrangements and review an agreed alternative.',480,'''<text x="30" y="35" font-size="24">Flow chart · visitor decision and alternative</text><g stroke="#426451" fill="white"><rect x="260" y="55" width="380" height="65" rx="20"/><rect x="260" y="150" width="380" height="70"/><path d="M450 250L610 315L450 380L290 315Z"/><rect x="30" y="280" width="220" height="80" rx="15"/><rect x="650" y="265" width="220" height="110"/></g><g fill="none" stroke="#426451" stroke-width="3" marker-end="url(#arrow)"><path d="M450 120V150"/><path d="M450 220V250"/><path d="M290 315H250"/><path d="M610 315H650"/></g><text x="305" y="95">Start: open Programme</text><text x="285" y="178">Choose session; read time</text><text x="285" y="204">and room</text><text x="348" y="322">Route usable?</text><text x="256" y="297">Yes</text><text x="615" y="297">No</text><text x="48" y="313">Follow route</text><text x="48" y="340">and finish</text><text x="668" y="295">Ask for access</text><text x="668" y="322">arrangements;</text><text x="668" y="349">review alternative</text><text x="30" y="435">The prototype provides information only. It does not submit a request.</text><text x="30" y="463">Actual event routes and agreed alternatives require a client check.</text>''')
model=P/'planning-model.html';s=model.read_text(encoding='utf-8')
for heading,file,height,alt in [
 ('Storyboard: twelve-second introduction','storyboard.svg',260,'Storyboard: festival title at zero to four seconds, venue approach at four to eight, venue label at eight to twelve; preserve captions.'),
 ('Site map','site-map.svg',300,'Programme parent links to Printmaking and Photography details; both return to Programme. Help is beside the programme.'),
 ('Decision flow','decision-flow.svg',480,'Choose a session and read time and room. If the route is usable, follow it; otherwise ask for access arrangements and review an alternative.')]:
 marker=f'<h2>{heading}</h2>';s=s.replace(marker,marker+f'<figure><a href="{file}"><img src="{file}" width="900" height="{height}" style="max-width:100%;height:auto" alt="{alt}"></a><figcaption>Editable vector model; open at full size to inspect labels. Text equivalent follows.</figcaption></figure>')
model.write_text(s,encoding='utf-8')
